For $1\leq P < \infty,$ the Lebesgue space $L^P(\mathbb{R}^{N})$ is a Banach space and for every complex valued measurable function  $f \in \mathbb{R}^{N}$ such that
\begin{eqnarray*}
\int_{\mathbb{R}^{N}}|f(\bm{t})|^P d\bm{t}< \infty,
\end{eqnarray*}
where norm is given by
\begin{eqnarray*}
\|f\|_{L^P(\mathbb{R}^{N})}=\left(\int_{\mathbb{R}^{N}}|f(\bm{t})|^P d\bm{t}\right)^{\frac{1}{P}}.
\end{eqnarray*}
In particular, $L^2(\mathbb{R}^{N})$ is a Hilbert space in which the  inner product is stated by
\begin{eqnarray*}
\langle f,g\rangle _{L^2(\mathbb{R}^{N})}=\int_{\mathbb{R}^{N}}f(\bm{t})\overline{g(\bm{t})}d\bm{t},
\end{eqnarray*}
here $\overline{g(\bm{t})}$ denotes the complex conjugate of $g(\bm{t}).$

The MFrFT of $f\in L^2(\mathbb{R}^{N}),$ of order $\bm\alpha=(\alpha_1, \alpha_2,\cdots,\alpha_{N}),$ ${\alpha_i} \in \left(-\pi,\pi\right)\backslash\{0\},$ for $i= 1,2,\cdots, {N}$ and $\lambda\in \mathbb{R}- \{0\},$ is given by
\begin{eqnarray}\label{P1eqn1}
\mathfrak{F}_{\bm{\alpha},\lambda}\left(f\right)\left(\bm{\xi}\right)=F_{\bm{\alpha},\lambda}\left(\bm{\xi}\right)= \int_{\mathbb{R}^{N}} f\left(\mathbf{x}\right)K_{\bm{\alpha},\lambda}\left(\mathbf{x},\bm{\xi}\right) \,d\mathbf{x},
\end{eqnarray}
where $ K_{{\bm{\alpha}},\lambda}\left(\bm{x},\bm{\xi}\right)= \displaystyle \prod_{i=1}^{N}K_{\alpha_{k},\lambda}\left(x_{k},\xi_{k}\right)$ and $K_{\alpha_{k},\lambda}\left(x_{k},\xi_{k}\right),~\mbox{for}~k=1,2,\cdots,{N},$ are defined by
\begin{eqnarray*}
K_{\alpha_{k},\lambda}\left(x_{k},\xi_{k}\right)=\begin{cases}
\frac{c(\alpha_{k})}{(\sqrt{2\pi})}e^{i\lambda^2\{a(\alpha_{k})[{x_{k}}^2+{\xi_{k}}^2-2b(\alpha_{k})x_{k}\xi_{k}]\}},  \alpha_{k}\notin \pi\mathbb{Z}\\
\Delta(x_{k}-\xi_{k}),\quad \quad \quad \quad\quad\quad\quad\quad\quad\quad \alpha_{k}\in 2\pi \mathbb{Z}\\
\Delta(x_{k}+\xi_{k}),\quad \quad\quad\quad\quad\quad\quad\quad\quad\quad  \alpha_{k}\in 2\pi \mathbb{Z}+\pi.
\end{cases}
\end{eqnarray*}
Here, $\mathbf{x}=(x_{1},x_{2}, x_{3},...,x_{N}),\quad a(\alpha_{k})=\frac{\cot(\alpha_{k})}{2}, \quad b(\alpha_{k})=\sec(\alpha_{k}),\quad c(\alpha_{k})=\sqrt{1-i\cot\alpha_{k}}.$

The kernel $K_{{\bm{\alpha}},\lambda}\left(\mathbf{x},\bm{\xi}\right)$ can be re-written as
\begin{eqnarray*}
K_{\bm{\alpha},\lambda}\left(\mathbf{x},\bm{\eta}\right)=\frac{c(\bm{\alpha}_\lambda)}{(\sqrt{2\pi})^{N}}e_{\bm{\alpha},\lambda^2}(\mathbf{x})e_{\bm{\alpha},\lambda^2}(\bm{\eta})e^{-i\lambda^2\sum_{k=1}^{N}x_{k}\eta_{k}\csc\alpha_{k}},
\end{eqnarray*}
where
\begin{eqnarray}
e_{\bm{\alpha},\lambda^2}(x)&=&e^{i\lambda^2 \sum_{k=1}^{N}a(\alpha_{k}){x_{k}}^2},\quad c(\bm\alpha_\lambda)=c(\alpha_1)c(\alpha_2) \cdots c(\alpha_{N})
\end{eqnarray}
and
$$ \bm\alpha_\lambda = \left(\cot^{-1}(\lambda^2\cot\alpha_1),\cot^{-1}(\lambda^2\cot\alpha_2),\cdots,\cot^{-1}(\lambda^2\cot\alpha_{N})\right).$$

A non-zero function  $\psi\in L^2(\mathbb{R}^{N})$ is  wavelet admissible if
\begin{eqnarray}
\displaystyle\int_{\mathbb{R}^{N}_{0}}|(\mathfrak{F}_{\bm{\alpha},\lambda}\psi)(\bm{u})|^2\frac{d\bm{u}}{|\bm{u}|_m}<\infty.
\end{eqnarray}

A wavelet admissible function is also known as a fractional wavelet or simply a wavelet.

Let $\psi,\phi\in L^2(\mathbb{R}^{N})$ be two wavelets and for any two functions $f,g \in L^2(\mathbb{R}^{N}).$ Also let $\sigma>0$ and $r,s\in \mathbb{C},$ then
\begin{enumerate}[label=(\roman*)]
\item {Linearity}:\label{P1PropMFrWT1}
$W^{\bm\alpha,\lambda}_{\psi}(r{f}+s{g})=r(W_{\psi}^{\bm\alpha,\lambda}{f})+s(W_{\psi}^{\bm\alpha,\lambda}{g})$.
This property shows that the MFrWT upholds the superposition principle, which is useful for multicomponent signal analysis.
\item{Anti-linearity}:\label{P1PropMFrWT2}
 $W_{\left(r{\psi}+s{\phi}\right)}^{\bm\alpha,\lambda}{f}=\overline{r}W_{{\psi}}{f}+\overline{s}W_{\phi}{f}.$
\item {Dilation}:\label{P1PropMFrWT3}
$(W_{\psi}^{\bm\alpha,\lambda}D_\sigma f)(\bm{a},\bm{b})=\displaystyle\frac{C'}{\sigma^{N}}W_{\psi}^{\bm\alpha,\frac{\lambda}{\sigma}}f(\sigma\bm{a},\sigma\bm{b}),$ where $D_\sigma$ is a dilation operator, which is given by $D_\sigma f(\bm{t})=f(\sigma \bm{t})$ and $C'=\sigma^{\frac{N}{2}}\overline{\left(\frac{c(\alpha_{\lambda})}{c\left(\alpha_{\frac{\lambda}{\sigma}}\right)}\right)},$
\item {Conjugacy}: \label{P1PropMFrWT4}
$(W_{\psi}^{\bm\alpha,\lambda}\overline{f})(\bm{a},\bm{b})=\overline{W_{\overline{\psi}}^{-\bm\alpha,\lambda}f(\bm{a},\bm{b})}.$
 \item {Parity}:\label{P1PropMFrWT5}
$(W_{\psi}^{\bm\alpha,\lambda}Pf)(\bm{a},\bm{b})=W_{\psi}^{\bm\alpha,\lambda}f(-\bm{a},-\bm{b}),$
Here, $P$ is the parity operator, which is defined by $Pf(\mathbf{x})=f(-\mathbf{x}).$

 \item{Translation}:\label{P1PropMFrWT6}
 $(W_\psi^{\bm\alpha,\lambda}\tau_{\mathbf{y}}f)(\bm{a},\bm{b})=e_{\bm{\alpha},-\lambda^2}(\bm{b})e_{\bm{\alpha},\lambda^2}(\bm{b}-\mathbf{y})e_{\bm{\alpha},\lambda^2}(\mathbf{y})(W_\psi^{\bm\alpha,\lambda}\check{f})(\bm{a},\bm{b}-\mathbf{y}),$ where  fractional translation operator $\tau_{\mathbf{y}}$ is given by $\tau_{\mathbf{y}}f(\mathbf{x})=f(\mathbf{x}-\mathbf{y})$ and $\displaystyle \check{f}(\bm{t})=f(\bm{t})e^{i\lambda^2\sum_{k=1}^{N}a(\alpha_k)2{t_{k}}y_k}.$
\end{enumerate}

(FrFT of $\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a},\bm{b}}(\bm{t})$) Suppose a non-zero function  $\psi\in L^2(\mathbb{R}^{N})$ is given, then 
\begin{eqnarray}
(\mathfrak{F}_{\bm{\alpha},\lambda}{\mathbf{\Psi}}_{\bm{\alpha},\lambda,\bm{a},\bm{b}})(\bm{\xi})&=&\overline{c(\bm\alpha_\lambda)}\sqrt{|\bm{a}|_m} e_{\bm{\alpha},\lambda^2}(\bm{b})e_{\alpha,\lambda^2}(\bm{\xi})e_{\bm{\alpha},-\lambda^2}(\bm{a}\bm{\xi})e^{-i\lambda^2\sum_{k=1}^{N}b_{k}\xi_{k}\csc\alpha_{k}}(\mathfrak{F}_{\bm{\alpha},\lambda}\psi)(\bm{a}\bm{\xi}).
\end{eqnarray}

\label{P1lemma1}
(FrFT of $W_{\psi}^{\bm\alpha,\lambda}{f}(\bm{a},\bm{b})$) Suppose $\psi$ be an admissible wavelet and for any arbitrary function $f\in L^2(\mathbb{R}^{N})$, then\\
\begin{eqnarray*}
\mathfrak{F}_{\bm{\alpha},\lambda}(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})(\bm{\xi})=\sqrt{|\bm{a}|_m}(\sqrt{2\pi})^{N} \frac{c(\bm\alpha_\lambda)}{\overline{c(\bm\alpha_\lambda)}}F(\bm{\xi}),\\
\end{eqnarray*}
where $F(\bm{\xi})=e_{\bm{\alpha},\lambda^2}(\bm{a}\bm{\xi})(\mathfrak{F}_{\bm{\alpha},\lambda}f)(\bm{\xi})\overline{(\mathfrak{F}_{\bm{\alpha},\lambda}\psi)(\bm{a}\bm{\xi})}.$

(Inner product relation for MFrWT){\label{P1innTh}}
Let $W_{\psi}^{\bm\alpha,\lambda}{f}$ and $W_{\psi}^{\bm\alpha,\lambda}{g}$  represent the MFrWT of functions $f$ and $g$ with respect to admissible wavelet $\psi$ respectively and then 
\begin{eqnarray}\label{P1eqn10}
\displaystyle\int_{\mathbb{R}^{N}_{0}}\displaystyle\int_{\mathbb{R}^{N}}(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\overline{(W_{\psi}^{\bm\alpha,\lambda}{g})(\bm{a},\bm{b})}\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}=C_{\bm{\alpha},\lambda}\langle f,g\rangle_{L^2(\mathbb{R}^{N})},
\end{eqnarray}
where
\begin{eqnarray}\label{P1eqn11}
C_{\bm{\alpha},\lambda}={(2\pi)^{N}}\displaystyle\int_{\mathbb{R}^{N}_{0}}|(\mathfrak{F}_{\bm{\alpha},\lambda}\psi)(\bm{u})|^2\frac{d\bm{u}}{|\bm{u}|_m}.
\end{eqnarray}

Treating $(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})$, $(W_{\psi}^{\bm\alpha,\lambda}{g})(\bm{a},\bm{b})$ as $L^2(\mathbb{R}^{N})$ are functions of some variable $\bm{b}$ and using the Parseval’s theorem
for the MFrFT  (\cite{kamalakkannan2020multidimensional}, Theorem 3.3) we have
\begin{align}\label{P1eqn12}
\displaystyle\int_{\mathbb{R}^{N}_{0}}\displaystyle\int_{\mathbb{R}^{N}}(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\overline{(W_{\psi}^{\bm\alpha,\lambda}{g})(\bm{a},\bm{b})}\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}=\displaystyle\int_{\mathbb{R}^{N}_{0}}\left(\displaystyle\int_{\mathbb{R}^{N}}\mathfrak{F}_{\bm{\alpha},\lambda}( (W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b}))(\bm{\xi})\overline{\mathfrak{F}_{\bm{\alpha},\lambda}(( W_{\psi}^{\bm\alpha,\lambda}{g})(\bm{a},\bm{b}))(\bm{\xi})}d\bm{\xi}\right)\frac{d\bm{a}}{|\bm{a}|_m^2}.
\end{align}
Now, using equation (\ref{p1eqn9}) in equation (\ref{P1eqn12}), we get
\begin{align*}
&\displaystyle\int_{\mathbb{R}^{N}_{0}}\displaystyle\int_{\mathbb{R}^{N}}(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\overline{(W_{\psi}^{\bm\alpha,\lambda}{g})(\bm{a},\bm{b})}\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}\\&=\displaystyle\int_{\mathbb{R}^{N}_{0}}\left(\int_{\mathbb{R}^{N}}\sqrt{|\bm{a}|_m}{(\sqrt{2\pi})^{N}}e_{\bm{\alpha},\lambda^2}(\bm{a}\bm{\xi})\overline{(\mathfrak{F}_{\bm{\alpha},\lambda}\psi)(\bm{a} \bm{\xi})}(\mathfrak{F}_{\bm{\alpha},\lambda} f)(\bm{\xi})\overline{\sqrt{|\bm{a}}|_m(\sqrt{2\pi})^Ne_{\bm{\alpha},\lambda^2}(\bm{a}\bm{\xi})\overline{(\mathfrak{F}_{\bm{\alpha},\lambda}\psi)(\bm{a} \bm{\xi})}(\mathfrak{F}_{\bm{\alpha},\lambda} g)(\bm{\xi})}d\bm{\xi}\right)\frac{d\bm{a}}{|\bm{a}|_m^2}\\
&=(2\pi)^{N}\displaystyle\int_{\mathbb{R}^{N}_{0}}\displaystyle\int_{\mathbb{R}^{N}}\overline{(\mathfrak{F}_{\bm{\alpha},\lambda}\psi)(\bm{a} \bm{\xi})}(\mathfrak{F}_{\bm{\alpha},\lambda}\psi)(\bm{a} \bm{\xi})(\mathfrak{F}_{\bm{\alpha},\lambda} f)(\bm{\xi})\overline{(\mathfrak{F}_{\bm{\alpha},\lambda} g)(\bm{\xi})}d\bm{\xi}\frac{d\bm{a}}{|\bm{a}|_m}\\
&=\int_{\mathbb{R}^{N}}(\mathfrak{F}_{\bm{\alpha},\lambda}f)(\bm{\xi})\overline{(\mathfrak{F}_{\bm{\alpha},\lambda}g)(\bm{\xi})}\left(\displaystyle\int_{\mathbb{R}^{N}_{0}}(2\pi)^{N}(\mathfrak{F}_{\bm{\alpha},\lambda}\psi)(\bm{a} \bm{\xi})\overline{(\mathfrak{F}_{\bm{\alpha},\lambda}\psi)(\bm{a} \bm{\xi})}\frac{d\bm{a}}{|\bm{a}|_m}\right)d\bm{\xi}.
\end{align*}
Thus we have
\begin{align*}
\displaystyle\int_{\mathbb{R}^{N}_{0}}\displaystyle\int_{\mathbb{R}^{N}}(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\overline{(W_{\psi}^{\bm\alpha,\lambda}{g})(\bm{a},\bm{b})}\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}&=\displaystyle\int_{\mathbb{R}^{N}}C_{\bm{\alpha},\lambda}(\mathfrak{F}_{\bm{\alpha},\lambda}f)(\bm{\xi})\overline{(\mathfrak{F}_{\bm{\alpha},\lambda}g)(\bm{\xi})}d\bm{\xi}\\
&=C_{\bm{\alpha},\lambda}\left\langle(\mathfrak{F}_{\bm{\alpha},\lambda}f)(\bm{\xi}),(\mathfrak{F}_{\bm{\alpha},\lambda}g)(\bm{\xi})\right\rangle_{L^2(\mathbb{R}^{N})}. 

\end{align*}   
Again, applying Parseval's inequality (\cite{kamalakkannan2020multidimensional}, Theorem 3.3), we get the required result. Fubini's theorem has been used to justify changing the order of integration.

\label{corofinnthe}
Suppose $\psi$ be an admissible wavelet and for any arbitrary function $f\in L^2(\mathbb{R}^{N})$. Then
\begin{eqnarray*}
\int_{\mathbb{R}^{N}_{0}}\int_{\mathbb{R}^{N}}(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\overline{(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})}\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}=C_{\bm{\alpha},\lambda}\|f\|^2_{L^2(\mathbb{R}^{N})}.
\end{eqnarray*}

(Reconstruction formula)
Suppose there exist an arbitrary function $f\in L^2(\mathbb{R}^{N})$ and an wavelet admissible function $\psi.$  Also let $C_{\bm{\alpha},\lambda}\neq 0 $ as defined in equation (\ref{P1eqn11}). The reconstruction formula for $f$ is then as follows:
\begin{eqnarray*}
f(\bm{t})=\frac{1}{C_{\bm{\alpha},\lambda}}\int_{\mathbb{R}^{N}_{0}}\int_{\mathbb{R}^{N}}(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a},\bm{b}}(\bm{t})\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}.
\end{eqnarray*}

We have
\begin{align*}
\left\langle W_{\psi}^{\bm\alpha,\lambda}{f}(\bm{a},\bm{b}),W_{\psi}^{\bm\alpha,\lambda}{g}(\bm{a},\bm{b})\right\rangle_{L^2(\mathbb{R}^{N}_0\times \mathbb{R}^{N})}
&=\int_{\mathbb{R}^{N}_{0}}\int_{\mathbb{R}^{N}} (W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\overline{(W_{\psi}^{\bm\alpha,\lambda}{g}(\bm{a},\bm{b}))}\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}\\
&=\int_{\mathbb{R}^{N}_{0}}\int_{\mathbb{R}^{N}} (W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\overline{\int_{\mathbb{R}^{N}}g(\bm{t})\overline{\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a},\bm{b}}(\bm{t})}d\bm{t}}\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}\\
&=\int_{\mathbb{R}^{N}_{0}}\int_{\mathbb{R}^{N}} (W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\int_{\mathbb{R}^{N}}\overline{g(\bm{t})}\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a},\bm{b}}(\bm{t})d\bm{t}\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}\\
&=\int_{\mathbb{R}^{N}}\overline{g(\bm{t})}\int_{\mathbb{R}^{N}_{0}}\int_{\mathbb{R}^{N}}( W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a},\bm{b}}(\bm{t})\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2} d\bm{t}\\
&=\left\langle\int_{\mathbb{R}^{N}_{0}}\int_{\mathbb{R}^{N}} (W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a},\bm{b}}(\bm{t})\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2},g(\bm{t})\right\rangle_{L^2(\mathbb{R}^{N})}.
\end{align*}
Using theorem (\ref{P1innTh})
\begin{eqnarray*}
\langle f,g\rangle_{L^2(\mathbb{R}^{N})} &=& \frac{1}{C_{\bm\alpha,\lambda}}\left\langle(W_{\psi}^{\bm\alpha,\lambda}{f}),(W_{\psi}^{\bm\alpha,\lambda}{g})\right\rangle_{L^2(\mathbb{R}^{N}_0\times \mathbb{R}^{N})}\\
&=&\frac{1}{C_{\bm\alpha,\lambda}}\left\langle\int_{\mathbb{R}^{N}_{0}}\int_{\mathbb{R}^{N}} (W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a},\bm{b}}(\bm{t})\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2},g(\bm{t})\right\rangle_{L^2(\mathbb{R}^{N})}\\
\Rightarrow \quad f(\bm{t})&=&\frac{1}{C_{\bm\alpha,\lambda}}\int_{\mathbb{R}^{N}_{0}}\int_{\mathbb{R}^{N}}(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a},\bm{b}}(\bm{t})\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}.
\end{eqnarray*}
Hence, the theorem follows.

(Reproducing kernel for the range of MFrWT)
Let $\psi$ be a wavelet. Also let $C_{\alpha,\lambda}\neq 0$ as defined in equation (\ref{P1eqn11}) and $(\bm{a}_0 , \bm{b}_0) \in \mathbb{R}^{N}\times \mathbb{R}^{N}_0$. Then, $F\in L^2\left(\mathbb{R}^{N}\times \mathbb{R}^{N}_0, \frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}\right)$ be the MFrWT of some $f \in L^2(\mathbb{R}^{N})$ iff
\begin{eqnarray*}
F(\bm{a}_0,\bm{b}_0)=\int_{\mathbb{R}^{N}_0}\int_{\mathbb{R}^{N}}
F(\bm{a},\bm{b})K_{\bm{\alpha},\lambda,\mathbf{\Psi}}(\bm{a}_0,\bm{b}_0;\bm{a},\bm{b})\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2},
\end{eqnarray*}
where $K_{\bm{\alpha},\lambda,\mathbf{\Psi}}(\bm{a}_0,\bm{b}_0:\bm{a},\bm{b})$ is the reproducing kernel which satisfies,
\begin{eqnarray*}
K_{\bm{\alpha},\lambda,\mathbf{\Psi}}(\bm{a}_0,\bm{b}_0;\bm{a},\bm{b})=\frac{1}{C_{\alpha,\lambda}}\int_{\mathbb{R}^{N}}\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a},\bm{b}}(\bm{t})\overline{\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a}_0,\bm{b}_0}(\bm{t})} d\bm{t}.
\end{eqnarray*}

Suppose for an arbitrary function $f \in L^2(\mathbb{R}^{N})$ be such that $W_{\psi}^{\bm\alpha,\lambda}{f}=F$, then we can write,
\begin{eqnarray*}
F(\bm{a}_0, \bm{b}_0)&=&(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a}_0, \bm{b}_0)\\
&=&\int_{\mathbb{R}^{N}}f(\bm{t})\overline{\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a}_0,\bm{b}_0}(\bm{t})} d\bm{t}\\
&=&\frac{1}{C_{\bm\alpha,\lambda}}\int_{\mathbb{R}^{N}}\int_{\mathbb{R}^{N}_{0}}\int_{\mathbb{R}^{N}}(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a},\bm{b}}(\bm{t})\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}\overline{\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a}_0,\bm{b}_0}(\bm{t})} d\bm{t}\\
&=&\int_{\mathbb{R}^{N}_{0}}\int_{\mathbb{R}^{N}}(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\left(\frac{1}{C_{\bm\alpha,\lambda}}\int_{\mathbb{R}^{N}}\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a},\bm{b}}(\bm{t})\overline{\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a}_0,\bm{b}_0}(\bm{t})} d\bm{t}\right)\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}.
\end{eqnarray*}
Hence,
\begin{eqnarray*}
F(\bm{a}_0,\bm{b}_0)=\int_{\mathbb{R}^{N}_0}\int_{\mathbb{R}^{N}}
F(\bm{a},\bm{b})K_{\bm{\alpha},\lambda,\mathbf{\Psi}}(\bm{a}_0,\bm{b}_0;\bm{a},\bm{b})\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2},
\end{eqnarray*}
where
$\displaystyle K_{\bm{\alpha},\lambda,\mathbf{\Psi}}(\bm{a}_0,\bm{b}_0;\bm{a},\bm{b})=\frac{1}{C_{\bm\alpha,\lambda}}\displaystyle\int_{\mathbb{R}^{N}}\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a},\bm{b}}(\bm{t})\overline{\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a}_0,\bm{b}_0}(\bm{t})}  d\bm{t}$.\\
On the other way round, Let's assume that the context holds only for the provided $F\in L^2\left(\mathbb{R}^{N}\times \mathbb{R}^{N}_0, \frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}\right)$ then required $f$ is determined by
\begin{align*}
\displaystyle\frac{1}{C_{\bm{\alpha},\lambda}}\int_{\mathbb{R}^{N}_0}\int_{\mathbb{R}^{N}}F(\bm{a},\bm{b})\mathbf{\Psi}_{\bm{\alpha},\lambda,\bm{a},\bm{b}}(\bm{t})\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}.
 \end{align*}
This completes the proof.

\label{lemofHUP}
Let $\psi$ be an admissible wavelet and for any function $f\in L^2(\mathbb{R}^{N}).$ Then,
\begin{eqnarray*}
\int_{\mathbb{R}_0^{N}}\int_{\mathbb{R}^{N}} \|\bm{\xi}\|^2|\mathfrak{F}_{\bm\alpha,\lambda} ( (W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\cdot))(\bm{\xi})|^2d\bm{\xi}\frac{d\bm{a}}{|\bm{a}|_m^2}&=&C_{\bm\alpha,\lambda}\int_{\mathbb{R}^{N}}\|\bm{\xi}\|^2|(\mathfrak{F}_{\bm\alpha,\lambda}f)(\bm{\xi})|^2d\bm{\xi},
\end{eqnarray*}
where $C_{\bm\alpha,\lambda}$ is as defined in equation (\ref{P1eqn11}).

(Heisenberg’s inequality of uncertainty for MFrWT) Let $\psi$ be an admissible wavelet and for any function $f\in L^2(\mathbb{R}^{N}),$ the MFrWT of $f$ with respect to the variable $\bm\alpha$ is specified by $(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})$ . Then
\begin{align*}
\left(\int_{\mathbb{R}_0^{N}}\int_{\mathbb{R}^{N}}\|\bm{b}\|^2|(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})|^2d\bm{b}\frac{d\bm{a}}{|\bm{a}|_m^2}\right)\left(\int_{\mathbb{R}^{N}} \|\bm{\xi}\|^2|(\mathfrak{F}_{\bm\alpha,\lambda}f)(\bm{\xi})|^2d\bm{\xi}\right) \geq P_{\bm\alpha,\lambda}C_{\bm\alpha,\lambda}\frac{{N}^2}{4}\|f\|^2_{L^2(\mathbb{R}^{N})},
\end{align*}
where $C_{\bm\alpha,\lambda}$ and $P_{\bm\alpha,\lambda}$ are defined in equation (\ref{P1eqn11}) and equation (\ref{P1eqn5aHUP}) respectively.

By substituting $(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\cdot)$ for $f(\cdot)$ in equation (\ref{P1eqn8HUP}), we obtain
\begin{align*}
\hspace{-1cm}\left(\int_{\mathbb{R}^{N}}\|\bm{b}\|^2|(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})|^2d\bm{b}\right)\left(\int_{\mathbb{R}^{N}} \|\bm{\xi}\|^2|\mathfrak{F}_{\bm\alpha,\lambda} ((W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},.))(\bm{\xi})|^2d\bm{\xi} \right) \geq P_{\bm\alpha,\lambda}\frac{{N}^2}{4}\|(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},.)\|^4_{L^2(\mathbb{R}^{N})}.
\end{align*}
Taking the square root of the above equation on both sides yields,
\begin{align*}
\hspace{-0.8cm}\left(\int_{\mathbb{R}^{N}}\|\bm{b}\|^2|(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})|^2d\bm{b}\right)^{\frac{1}{2}}\left(\int_{\mathbb{R}^{N}} \|\bm{\xi}\|^2|\mathfrak{F}_{\bm\alpha,\lambda} ((W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b}))(\bm{\xi})|^2d\bm{\xi}\right)^{\frac{1}{2}} \geq {P^{\frac{1}{2}}_{\bm\alpha,\lambda}}\frac{{N}}{2}\int_{\mathbb{R}^{N}}|(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})|^2d\bm{b}.
\end{align*}
Now, we Integrate above equation with respect to the measure $\frac{d\bm{a}}{|\bm{a}|_m^2}$, we've
\begin{align*}
\hspace{-2cm}\int_{\mathbb{R}_0^{N}}\left(\int_{\mathbb{R}^{N}}\|\bm{b}\|^2|(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})|^2d\bm{b}\right)^{\frac{1}{2}}\left(\int_{\mathbb{R}^{N}} \|\bm{\xi}\|^2|\mathfrak{F}_{\bm\alpha,\lambda} (W_{\psi}^{\bm\alpha,\lambda}{f}(\bm{a},\bm{b}))(\bm{\xi})|^2d\bm{\xi}\right)^{\frac{1}{2}}\frac{d\bm{a}}{|\bm{a}|_m^2}\\ \geq {P^{\frac{1}{2}}_{\bm\alpha,\lambda}}\frac{{N}}{2}\int_{\mathbb{R}_0^{N}} \int_{\mathbb{R}^{N}}|(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})|^2\frac{d\bm{a}d\bm{b}}{|\bm{a}|_m^2}.
\end{align*}
Using Holder's inequality and corollary (\ref{corofinnthe}), we have
\begin{align*}
\left(\int_{\mathbb{R}_0^{N}}\int_{\mathbb{R}^{N}}\|\bm{b}\|^2|(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})|^2d\bm{b}\frac{d\bm{a}}{|\bm{a}|_m^2}\right)^{\frac{1}{2}}\left(\displaystyle\int_{\mathbb{R}_0^{N}}\int_{\mathbb{R}^{N}}\|\bm{\xi}\|^2|\mathfrak{F}_{\bm\alpha,\lambda} ((W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b}))(\bm{\xi})|^2d\bm{\xi} \frac{d\bm{a}}{|\bm{a}|_m^2}\right)^{\frac{1}{2}} \\
\geq {P^{\frac{1}{2}}_{\bm\alpha,\lambda}}\frac{{N}}{2}C_{\bm\alpha,\lambda}\|f\|^2_{L^2(\mathbb{R}^{N})}.
\end{align*}
Squaring both sides and applying lemma (\ref{lemofHUP}), we obtain
\begin{align*}
\left(\int_{\mathbb{R}_0^{N}}\int_{\mathbb{R}^{N}}\|\bm{b}\|^2|(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})|^2d\bm{b}\frac{d\bm{a}}{|\bm{a}|_m^2}\right)\left(C_{\bm\alpha,\lambda}\int_{\mathbb{R}^{N}}\|\bm{\xi}\|^2|(\mathfrak{F}_{\bm\alpha,\lambda}f)(\bm{\xi})|^2d\bm{\xi}\right)\geq P_{\bm\alpha,\lambda} \frac{{N}^2}{4}C^2_{\bm\alpha,\lambda}\|f\|^4_{L^2(\mathbb{R}^{N})},
\end{align*}
i.e.,
\begin{align*}
\left(\int_{\mathbb{R}_0^{N}}\int_{\mathbb{R}^{N}}\|\bm{b}\|^2|(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})|^2d\bm{b}\frac{d\bm{a}}{|\bm{a}|_m^2}\right)\left(\int_{\mathbb{R}^{N}}\|\bm{\xi}\|^2|(\mathfrak{F}_{\bm\alpha,\lambda}f)(\bm{\xi})|^2d\bm{\xi}\right)\geq P_{\bm\alpha,\lambda} C_{\bm\alpha,\lambda}\frac{{N}^2}{4}\|f\|^4_{L^2(\mathbb{R}^{N})}.
\end{align*}
This concludes the proof for this section.

\label{P1Th1LUP}
(Local uncertainty inequality for MFrWT) If $\psi$  is an admissible wavelet and $\theta$ be such that $0 < \theta < \frac{N}{2}.$ Then, for every measurable subsets $K$ of $\mathbb{R}^{N},$ there exist constant $A_\theta$  and for all $f\in L^2(\mathbb{R}^{N})$ such that 

\begin{eqnarray*}
\int_K|(\mathfrak{F}_{\bm\alpha,\lambda}f)(\boldsymbol\eta)|^2d\boldsymbol\eta\leq\frac{|c(\bm\alpha_\lambda)|^2}{C_{\bm\alpha,\lambda}}A_\theta\frac{|\sin\bm\alpha|_m}{(\lambda^2)^{N}}(\lambda(K))^{\frac{2\theta}{N}}\int_{\mathbb{R}_0^{N}}\int_{\mathbb{R}^{N}}\|\bm{b}\|^{2\theta} \left|(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\right|^2d\bm{b}\frac{d\bm{a}}{|\bm{a}|_m^2}.
\end{eqnarray*}

By substituting $W_{\psi}^{\bm\alpha,\lambda}{f}(\bm{a},\cdot)$ for $f(\cdot)$ in equation (\ref{P1eqn2LUP}), we obtain

\begin{eqnarray*}
\int_{K}|\mathfrak{F}_{\bm\alpha,\lambda}((W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b}))(\boldsymbol\eta)|^2d\boldsymbol\eta \leq |c(\bm\alpha_\lambda)|^2 A_\theta\frac{|\sin\bm\alpha|_m}{(\lambda^2)^{N}}(\lambda(K))^{\frac{2\theta}{N}}\|\|\bm{b}\|^\theta (W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\|^2_{L^2(\mathbb{R}^{N})}.
\end{eqnarray*}
Now we integrate either side of above equation with respect to  $\frac{d\bm{a}}{|\bm{a}|_m^2},$ we get
\begin{eqnarray*}
\int_{\mathbb{R}_0^{N}}\int_{K}|\mathfrak{F}_{\bm\alpha,\lambda}((W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b}))(\boldsymbol\eta)|^2\frac{d\bm{a}}{|\bm{a}|_m^2}d\boldsymbol\eta\leq|c(\bm\alpha_\lambda)|^2 A_\theta\frac{|\sin\bm\alpha|_m}{(\lambda^2)^{N}}(\lambda(K))^{\frac{2\theta}{N}}\int_{\mathbb{R}_0^{N}}\|\|\bm{b}\|^\theta (W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\|^2_{L^2(\mathbb{R}^{N})}\frac{d\bm{a}}{|\bm{a}|_m^2},
\end{eqnarray*}
and using theorem (\ref{P1innTh}),
\begin{eqnarray*}
{C_{\bm\alpha,\lambda}}\int_{K}|(\mathfrak{F}_{\bm\alpha,\lambda}f)|^2d\boldsymbol\eta\leq |c(\bm\alpha_\lambda)|^2 A_\theta \frac{|\sin\bm\alpha|_m}{(\lambda^2)^{N}}(\lambda(K))^{\frac{2\theta}{N}}\int_{\mathbb{R}_0^{N}}\int_{\mathbb{R}^{N}}\left|\|\bm{b}\|^\theta (W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\right|^2d\bm{b}\frac{d\bm{a}}{|\bm{a}|_m^2}.
\end{eqnarray*}
This gives
\begin{eqnarray*}
\int_{K}|(\mathfrak{F}_{\bm\alpha,\lambda}f)|^2d\boldsymbol\eta\leq \frac{|c(\bm\alpha_\lambda)|^2}{C_{\bm\alpha,\lambda}} A_\theta \frac{|\sin\bm\alpha|_m}{(\lambda^2)^{N}}(\lambda(K))^{\frac{2\theta}{N}}\int_{\mathbb{R}_0^{N}}\int_{\mathbb{R}^{N}}\|\bm{b}\|^{2\theta} \left|(W_{\psi}^{\bm\alpha,\lambda}{f})(\bm{a},\bm{b})\right|^2d\bm{b}\frac{d\bm{a}}{|\bm{a}|_m^2}.
\end{eqnarray*}
This concludes the proof.

